import { prisma } from '../../../lib/prisma';
import { NextRequest, NextResponse } from 'next/server';

export async function POST(request: NextRequest) {
    const { userId, referrerId } = await request.json();

    if (!userId || !referrerId) {
        return NextResponse.json({ error: 'Missing userId or referrerId' }, { status: 400 });
    }

    try {
        const existingUser = await prisma.user.findUnique({
            where: { telegramId: parseInt(userId) },
        });

        if (existingUser) {
            return NextResponse.json({ message: 'User already exists. No points awarded.' });
        }

        const referrer = await prisma.user.findUnique({
            where: { telegramId: parseInt(referrerId) },
        });

        if (!referrer) {
            return NextResponse.json({ error: 'Referrer not found' }, { status: 404 });
        }

        const newUser = await prisma.user.create({
            data: {
                telegramId: parseInt(userId),
                referredByTelegramId: referrer.telegramId,
                isNewUser: false
            },
        });

        await prisma.user.update({
            where: { telegramId: referrer.telegramId },
            data: { points: { increment: 500 } },
        });

        return NextResponse.json({ success: true, newUser, referrerPoints: referrer.points + 500 });
    } catch (error) {
        console.error('Error saving referral:', error);
        return NextResponse.json({ error: 'Failed to save referral' }, { status: 500 });
    }
}

export async function GET(request: NextRequest) {
    const userId = request.nextUrl.searchParams.get('userId');

    if (!userId) {
        return NextResponse.json({ error: 'Missing userId' }, { status: 400 });
    }

    try {
        const user = await prisma.user.findUnique({
            where: { telegramId: parseInt(userId) },
            include: {
                referrals: true,
                referredBy: true
            }
        });

        if (!user) {
            return NextResponse.json({ error: 'User not found' }, { status: 404 });
        }

        const response = {
            referrer: user.referredBy ? {
                telegramId: user.referredBy.telegramId,
                username: user.referredBy.username,
                firstName: user.referredBy.firstName,
                lastName: user.referredBy.lastName
            } : null,
            referrals: user.referrals.map((ref: { telegramId: number; username: string; firstName: string; lastName: string; }) => ({
                telegramId: ref.telegramId,
                username: ref.username,
                firstName: ref.firstName,
                lastName: ref.lastName
            }))
        };

        return NextResponse.json(response);
    } catch (error) {
        console.error('Error fetching referrals:', error);
        return NextResponse.json({ error: 'Failed to fetch referrals' }, { status: 500 });
    }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function POST(req: Request) {
    try {
        const { userId, checkpointId, points, day, bgImage  } = await req.json();

        const numericUserId = Number(userId);
        if (isNaN(numericUserId)) {
            return NextResponse.json({ error: "Invalid userId" }, { status: 400 });
        }

        const user = await prisma.user.findUnique({ where: { telegramId: numericUserId } });

        if (!user) {
            return NextResponse.json({ error: 'User not found' }, { status: 404 });
        }

        if (user.claimedCheckpoints.includes(checkpointId)) {
            return NextResponse.json({ error: 'Already checked in' }, { status: 400 });
        }

        const today = new Date();
        today.setHours(0, 0, 0, 0);

        // If user has never checked in before or is starting over
        if (!user.lastCheckIn || user.streak === 0) {
            if (day !== "Day 01") {
                return NextResponse.json({ error: 'Must start with Day 01' }, { status: 400 });
            }

            const updatedUser = await prisma.user.update({
                where: { telegramId: numericUserId },
                data: {
                    points: { increment: points },
                    claimedCheckpoints: { push: checkpointId },
                    gifts: { push: bgImage ? bgImage : [] },
                    streak: 1,
                    lastCheckIn: today,
                    lastClaimedDay: day
                },
            });

            return NextResponse.json({ 
                points: updatedUser.points, 
                streak: updatedUser.streak,
                lastClaimedDay: updatedUser.lastClaimedDay 
            });
        }

        // For existing users, check the time difference
        const lastCheckIn = new Date(user.lastCheckIn);
        lastCheckIn.setHours(0, 0, 0, 0);

        const daysDifference = Math.floor((today.getTime() - lastCheckIn.getTime()) / (1000 * 60 * 60 * 24));

        // If trying to claim on the same day
        if (daysDifference === 0) {
            return NextResponse.json({ error: 'Already claimed today' }, { status: 400 });
        }

        // If streak is broken (more than 1 day has passed)
        if (daysDifference > 1) {
            if (day !== "Day 01") {
                return NextResponse.json({ error: 'Streak broken. Must start from Day 01' }, { status: 400 });
            }

            // Reset streak and start over
            const updatedUser = await prisma.user.update({
                where: { telegramId: numericUserId },
                data: {
                    points: { increment: points },
                    claimedCheckpoints: [checkpointId],
                    streak: 1,
                    gifts: bgImage ? [bgImage] : [],
                    lastCheckIn: today,
                    lastClaimedDay: "Day 01"
                },
            });

            return NextResponse.json({ 
                points: updatedUser.points, 
                streak: updatedUser.streak,
                lastClaimedDay: updatedUser.lastClaimedDay 
            });
        }

        // For consecutive days, verify correct day is being claimed
        const currentDayNumber = parseInt(user.lastClaimedDay.split(" ")[1]);
        const nextDayNumber = currentDayNumber + 1;
        const expectedNextDay = `Day ${String(nextDayNumber).padStart(2, '0')}`;

        if (day !== expectedNextDay) {
            return NextResponse.json({ 
                error: `Must claim ${expectedNextDay} next` 
            }, { status: 400 });
        }

        // Update user with new streak and checkpoint
        const updatedUser = await prisma.user.update({
            where: { telegramId: numericUserId },
            data: {
                points: { increment: points },
                claimedCheckpoints: { push: checkpointId },
                gifts: { push: bgImage ? bgImage : [] },
                streak: { increment: 1 },
                lastCheckIn: today,
                lastClaimedDay: day
            },
        });

        return NextResponse.json({ 
            points: updatedUser.points, 
            streak: updatedUser.streak,
            lastClaimedDay: updatedUser.lastClaimedDay 
        });

    } catch (error) {
        console.error('Check-in error:', error);
        return NextResponse.json({ error: `Something went wrong: ${error}` }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { prisma } from "../../../lib/prisma";

export async function POST(request: Request) {
  try {
    const { telegramId, points } = await request.json();

    if (!telegramId) {
      return NextResponse.json({ error: "Telegram ID is required." }, { status: 400 });
    }

    const telegramIdInt = parseInt(telegramId, 10);

    if (isNaN(telegramIdInt)) {
      return NextResponse.json({ error: "Invalid Telegram ID." }, { status: 400 });
    }   

    const user = await prisma.user.findUnique({
      where: { telegramId: telegramIdInt },
    });

    if (!user) {
      return NextResponse.json({ error: "User not found." }, { status: 404 });
    }

    if (user.hasClaimedWelcomePoints) {
      return NextResponse.json(
        { error: "You have already claimed your welcome points." },
        { status: 403 }
      );
    }

    const updatedUser = await prisma.user.update({
      where: { telegramId: telegramIdInt },
      data: {
        points: { increment: points },
        hasClaimedWelcomePoints: true,
        isNewUser: false,
      },
    });

    return NextResponse.json({ success: true, user: updatedUser }, { status: 200 });
  } catch (error) {
    console.error("Error claiming points:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

import { prisma } from '../../../lib/prisma';
import { NextResponse } from 'next/server';

interface TaskCompletionRequest {
  userId: string;
  taskId: string;
  points: number;
}

export async function POST(request: Request): Promise<NextResponse> {
  try {
    const { userId, taskId, points }: TaskCompletionRequest = await request.json();

    // Validate and convert `userId` (telegramId) to an integer
    const telegramId = parseInt(userId, 10);
    if (isNaN(telegramId)) {
      return NextResponse.json({ error: 'Invalid user ID.' }, { status: 400 });
    }

    // Find the user by `telegramId`
    const user = await prisma.user.findFirst({
      where: { telegramId },
    });

    if (!user) {
      return NextResponse.json({ error: 'User not found.' }, { status: 404 });
    }

    // Check if the task has already been completed by the user
    const taskCompleted = await prisma.taskCompletion.findFirst({
      where: { userId: user.id, taskId },
    });

    if (taskCompleted) {
      return NextResponse.json({ error: 'Task already completed.' }, { status: 400 });
    }

    // Ensure points value is provided and valid
    if (typeof points !== 'number' || points <= 0) {
      return NextResponse.json({ error: 'Invalid points value.' }, { status: 400 });
    }

    // Create a task completion record
    await prisma.taskCompletion.create({
      data: { userId: user.id, taskId },
    });

    // Increment the user's points with the provided value
    await prisma.user.update({
      where: { id: user.id },
      data: { points: { increment: points } },
    });

    return NextResponse.json({
      success: true,
      message: `Task completed! You earned ${points} points.`,
    });
  } catch (error) {
    console.error('Error completing task:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

